import{_ as i,o as t,c as e,a3 as l}from"./chunks/framework.D1iekJsc.js";const k=JSON.parse('{"title":"LAN アクセスの有効化（Ollama）","description":"OLLAMA_HOST=0.0.0.0 とファイアウォールを設定し、スマホ MiniTavern から PC 上の Ollama へ LAN 接続。","frontmatter":{"title":"LAN アクセスの有効化（Ollama）","description":"OLLAMA_HOST=0.0.0.0 とファイアウォールを設定し、スマホ MiniTavern から PC 上の Ollama へ LAN 接続。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"LAN アクセスの有効化（Ollama） · MiniTavern Docs"}],["meta",{"property":"og:description","content":"OLLAMA_HOST=0.0.0.0 とファイアウォールを設定し、スマホ MiniTavern から PC 上の Ollama へ LAN 接続。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/ollama/lan"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/ollama/lan"}]]},"headers":[],"relativePath":"ja/ollama/lan.md","filePath":"ja/ollama/lan.md","lastUpdated":1787224147000}'),s={name:"ja/ollama/lan.md"};function n(o,a,r,h,p,d){return t(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="lan-アクセスの有効化-ollama" tabindex="-1">LAN アクセスの有効化（Ollama） <a class="header-anchor" href="#lan-アクセスの有効化-ollama" aria-label="Permalink to &quot;LAN アクセスの有効化（Ollama）&quot;">​</a></h1><p>既定では Ollama は本機のみをリスンすることが多い。スマホから PC へつなぐには、<strong>すべての NIC</strong>（<code>0.0.0.0</code>）をリスンさせ、ファイアウォールでポートを開放する。</p><h2 id="ollama-host-の設定" tabindex="-1"><code>OLLAMA_HOST</code> の設定 <a class="header-anchor" href="#ollama-host-の設定" aria-label="Permalink to &quot;`OLLAMA_HOST` の設定&quot;">​</a></h2><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><ol><li>スタートメニューで「環境変数」→「システム環境変数の編集」→「環境変数」。</li><li>「ユーザー変数」または「システム変数」に新規：</li></ol><table tabindex="0"><thead><tr><th>変数名</th><th>変数値</th></tr></thead><tbody><tr><td><code>OLLAMA_HOST</code></td><td><code>0.0.0.0</code></td></tr></tbody></table><ol start="3"><li>保存後、Ollama を<strong>完全終了して再起動</strong>（トレイアイコンから終了→起動）。</li></ol><p>PowerShell（現在のセッションのみ一時）：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OLLAMA_HOST </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;0.0.0.0&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># その後 ollama アプリまたはサービスを再起動</span></span></code></pre></div><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><p>一時（現在の端末セッション）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">launchctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setenv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OLLAMA_HOST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span></span></code></pre></div><p>その後 Ollama アプリを終了して再起動。再起動後に効かない場合は shell 設定や LaunchAgent へ；または：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OLLAMA_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0.0.0</span></span></code></pre></div><p>その環境で Ollama サービスが起動していることを確認。最も確実なのは：<strong>環境変数設定後に Ollama を再起動</strong>。</p><h2 id="ファイアウォールでポート-11434-を開放" tabindex="-1">ファイアウォールでポート 11434 を開放 <a class="header-anchor" href="#ファイアウォールでポート-11434-を開放" aria-label="Permalink to &quot;ファイアウォールでポート 11434 を開放&quot;">​</a></h2><ul><li><strong>Windows</strong>：システム設定 → プライバシーとセキュリティ → Windows セキュリティ → ファイアウォール → アプリの許可；または受信規則で TCP <code>11434</code>。</li><li><strong>macOS</strong>：システム設定 → ネットワーク → ファイアウォール；初回アクセスで Ollama を許可、またはポート開放。</li></ul><h2 id="lan-の検証" tabindex="-1">LAN の検証 <a class="header-anchor" href="#lan-の検証" aria-label="Permalink to &quot;LAN の検証&quot;">​</a></h2><ol><li>PC の IP を調べる（<a href="/ultra_guides/ja/quickstart#step-4pc-の-lan-ip-を調べる">クイックスタート Step 4</a>）。</li><li><strong>同一 Wi‑Fi の別デバイス</strong>のブラウザで：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://YOUR_PC_IP:11434</span></span></code></pre></div><p>開けば、または Ollama 関連の応答があれば、LAN は通っている。</p><h2 id="minitavern-用のアドレス" tabindex="-1">MiniTavern 用のアドレス <a class="header-anchor" href="#minitavern-用のアドレス" aria-label="Permalink to &quot;MiniTavern 用のアドレス&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://YOUR_PC_IP:11434/v1</span></span></code></pre></div><p>注意：</p><ul><li>LAN IP を使い、<strong><code>localhost</code> は使わない</strong></li><li><code>/v1</code> 接尾辞推奨（OpenAI 互換パス）</li></ul><h2 id="次のステップ" tabindex="-1">次のステップ <a class="header-anchor" href="#次のステップ" aria-label="Permalink to &quot;次のステップ&quot;">​</a></h2><p><a href="/ultra_guides/ja/connect-app/minitavern">MiniTavern での設定</a></p>',27)])])}const g=i(s,[["render",n]]);export{k as __pageData,g as default};
